total += 5;
let total = total * 2; // shadowing: un binding nuevo

let attempts: u8 = 3;
let ratio: f64 = 0.75;
let enabled: bool = attempts < 5 && ratio > 0.5;

fn double(value: u32) -> u32 {
    value * 2
}

fn total(items: u32, fee: u32) -> u32 {
    double(items) + fee
}

fn first_word(text: &str) -> Option<&str> {
    text.split_whitespace().next()
}

let owned = String::from("hello rust");
let first = first_word(&owned); // préstamo inmutable; owned sigue disponible
